import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';
import { BUILDING_CONFIG } from '../Config/BuildingConfig';
import { HallEvents } from '../HallEvents';

export interface UpgradeRequestPayload {
    buildingId: number;
    onSuccess?: () => void;
    onFail?: (reason: 'max_level' | 'insufficient') => void;
}

export class UpgradeSystem implements System {
    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.UPGRADE_REQUEST, this._onUpgrade, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.UPGRADE_REQUEST, this._onUpgrade, this);
        this._world = null!;
    }

    onTick(world: World, dt: number): void {
        
    }

    private _onUpgrade(req: UpgradeRequestPayload): void {
        const building = this._findBuilding(req.buildingId);
        if (!building) { req.onFail?.('max_level'); return; }

        const config = BUILDING_CONFIG[building.typeId];
        if (!config) { req.onFail?.('max_level'); return; }
        if (building.level >= config.maxLevel) { req.onFail?.('max_level'); return; }

        const cost = config.upgradeCost(building.level);
        this._world.bus.emit(HallEvents.SPEND_REQUEST, {
            amount: cost,
            source: 'upgrade',
            onSuccess: () => {
                building.level++;
                building.recalc(config);
                this._world.bus.emit(HallEvents.UPGRADE_COMPLETED, building);
                req.onSuccess?.();
            },
            onFail: () => req.onFail?.('insufficient'),
        });
    }

    private _findBuilding(id: number): BuildingEntity | null {
        for (const b of this._world.query<BuildingEntity>('building')) {
            if (b.id === id) return b;
        }
        return null;
    }
}